window.RTR_T=window.RTR_T||{};RTR_T["n1"]={"code": "N-1", "title": "Oftalmologiyaning rivojlanish tarixi. Ko‘ruv organi anatomiyasi. Ko‘zning ko‘rish faoliyati", "hours": 2, "minutes": 80, "goal": "O‘quvchilarda oftalmologiya fanining mazmuni, qisqacha rivojlanish tarixi, ko‘ruv organining anatomik tuzilishi va ko‘zning asosiy ko‘rish funksiyalari to‘g‘risida bilim hamda ularni hamshiralik amaliyotida qo‘llash ko‘nikmalarini shakllantirish.", "plan": ["“Oftalmologiya” fani haqida tushuncha va uning tibbiyot fanlari orasidagi o‘rni", "Oftalmologiya fanining rivojlanish tarixi", "Ko‘ruv organi anatomiyasi", "Ko‘ruv organining faoliyati (ko‘rish funksiyalari)"], "outcomes": ["Oftalmologiya fani haqida tushuncha va uning tibbiyot fanlari orasidagi o‘rnini aytib beradi.", "Oftalmologiya fanining qisqacha rivojlanish tarixini, unga hissa qo‘shgan olimlarni sanab beradi.", "Ko‘zning tuzilishi, pardalari, ichki muhitlari va yordamchi apparatini aytib, rasmda ko‘rsatib beradi.", "Ko‘zning ko‘rish faoliyati: markaziy, periferik, rang, yorug‘lik va binokulyar ko‘rishni tushuntirib beradi."], "keywords": ["oftalmologiya", "ko‘ruv analizatori", "ko‘z olmasi", "shox parda", "sklera", "tomirli parda", "to‘r parda", "gavhar", "shishasimon tana", "ko‘rish o‘tkirligi", "ko‘ruv maydoni", "rang ko‘rish", "binokulyar ko‘rish"], "methods": [{"name": "Tezkor savol-javob (blits-so‘rov)", "stage": "Tayanch bilimlarni faollashtirish (5 daqiqa)", "goal": "Anatomiya va fiziologiya fanlaridan olingan bilimlarni yodga tushirish, yangi mavzuga ko‘prik yaratish.", "steps": ["O‘qituvchi qisqa, aniq javob talab qiladigan savollarni ketma-ket beradi.", "O‘quvchilar navbat bilan 10–15 soniyada javob beradi.", "Noto‘g‘ri javoblar darhol boshqa o‘quvchi tomonidan to‘g‘rilanadi."], "task": ["“Oftalmos” so‘zi nimani anglatadi?", "Analizator necha qismdan iborat?", "Ko‘ruv organining asosiy va yordamchi qismlarini ayting.", "Ko‘ruv markazi bosh miyaning qaysi bo‘lagida joylashgan?"]}, {"name": "Taqdimot va vizual ko‘rgazmali bayon (mini-ma’ruza)", "stage": "Yangi materialni bayon qilish (35 daqiqa)", "goal": "Mavzuning nazariy holatlarini slaydlar, infografika va animatsiya yordamida tushunarli yetkazish.", "steps": ["Reja asosida har bir savol slaydlar orqali sharhlanadi.", "Ko‘z olmasi kesimi rasmida har bir parda va muhit ko‘rsatgich bilan ko‘rsatiladi.", "“Nur yo‘li” animatsiyasi orqali ko‘rish jarayoni namoyish etiladi.", "O‘quvchilar asosiy tushunchalarni daftarga yozib boradi."], "task": ["Slaydlar: RTR → “Taqdimot” bo‘limi", "Animatsiya: RTR → “Media” bo‘limi"]}, {"name": "Klaster (tarmoqlash)", "stage": "Yangi materialni tizimlashtirish (7 daqiqa)", "goal": "Ko‘ruv organining tuzilmalari o‘rtasidagi bog‘liqlikni grafik ko‘rinishda ifodalash.", "steps": ["Doska markaziga “KO‘RUV ORGANI” so‘zi yoziladi.", "O‘quvchilar undan tarmoqlar chiqaradi: ko‘z olmasi → pardalar → qismlari; ichki muhitlar; yordamchi apparat.", "Har bir tarmoq oxiriga tuzilmaning vazifasi yoziladi.", "Tayyor klaster ma’ruzadagi jadval bilan solishtiriladi."], "task": ["Ko‘z olmasining uch pardasi va ularning qismlari bo‘yicha klaster tuzing."]}, {"name": "“Galereya bo‘ylab sayohat”", "stage": "Mustahkamlash (15 daqiqa)", "goal": "Kichik guruhlarda ishlab, bir-birining javoblarini baholash va to‘ldirish orqali bilimlarni mustahkamlash.", "steps": ["Guruh 3 ta kichik guruhga bo‘linadi (“Ibn Sino”, “Gelmgols”, “Filatov”).", "Har bir guruh flipchart varag‘ida o‘z savoliga javob yozadi (5 daqiqa).", "Varaqlar soat mili bo‘yicha almashtiriladi, har bir guruh boshqa guruh javobini boshqa rangli marker bilan to‘ldiradi.", "Varaq egasiga qaytgach, guruh sardori yakuniy javobni taqdim etadi, o‘qituvchi xulosa qiladi."], "task": ["1-guruh: Oftalmologiya rivojiga hissa qo‘shgan olimlar va ularning kashfiyotlari (vaqt chizig‘i).", "2-guruh: Ko‘z olmasining pardalari va ichki muhitlari (sxema chizib, belgilash).", "3-guruh: Ko‘zning 5 ta ko‘rish funksiyasi va ularni tekshirish usullari (jadval)."]}, {"name": "Insert (belgilar bilan o‘qish)", "stage": "Mustaqil o‘qish (uyga vazifa)", "goal": "Matnni tanqidiy va diqqat bilan o‘qish ko‘nikmasini rivojlantirish.", "steps": ["O‘quvchi ma’ruza matnini o‘qib, satr chetiga belgi qo‘yadi: “V” – bilardim; “+” – yangi ma’lumot; “–” – boshqacha o‘ylardim; “?” – tushunarsiz.", "Belgilar bo‘yicha jadval to‘ldiriladi.", "Keyingi darsda “?” belgili savollar muhokama qilinadi."], "task": ["“Ko‘ruv organining faoliyati” bo‘limini Insert usulida o‘qing va jadval tuzing."]}, {"name": "Test va interaktiv mashqlar", "stage": "Nazorat va baholash (10 daqiqa)", "goal": "Mavzuning o‘zlashtirilishini xolis baholash.", "steps": ["O‘quvchilar RTRdagi 30 savollik testni kompyuter yoki smartfonda yechadi.", "Natija avtomatik hisoblanadi, xatolar tahlil qilinadi.", "“Atama – ta’rif” moslashtirish mashqi bajariladi."], "task": ["RTR → “Nazorat” bo‘limi"]}], "review": ["Oftalmologiya qanday fan va uning asosiy vazifalari nimalardan iborat?", "Nima uchun ko‘rishning pasayishi ijtimoiy muammo hisoblanadi?", "Qaysi umumiy kasalliklar ko‘zda o‘z aksini topadi? Misollar keltiring.", "Abu Ali ibn Sino oftalmologiya rivojiga qanday hissa qo‘shgan?", "Gelmgols, Snellen va Gullstrandning kashfiyotlarini ayting.", "Ko‘ruv analizatori qanday qismlardan iborat?", "Ko‘z olmasining uch pardasini va ularning qismlarini sanab bering.", "Shox pardaning xususiyatlarini ayting. Nima uchun unga tushgan yot jism kuchli og‘riq beradi?", "Qorachiqning vazifasi nima va uni qaysi muskullar boshqaradi?", "Kiprikli tananing qanday vazifalari bor?", "Tayoqchalar va kolbachalarning farqi nimada?", "Nima uchun ko‘ruv nervi diski “ko‘r dog‘” deb ataladi?", "Ko‘zning ichki tiniq muhitlarini ayting. Ko‘z ichi bosimining normasi qancha?", "Ko‘z yoshi qanday yo‘l bilan burun bo‘shlig‘iga tushadi?", "Ko‘z olmasini harakatlantiruvchi muskullarni va ularni innervatsiya qiluvchi nervlarni ayting.", "Ko‘zning 5 ta asosiy ko‘rish funksiyasini sanab bering.", "Ko‘rish o‘tkirligi qanday tekshiriladi va hujjatga qanday yoziladi?", "Gemeralopiya nima va uning oldini olish uchun qanday maslahat beriladi?"], "tasks": [{"title": "1-topshiriq. Ko‘z olmasi sxemasini belgilash", "text": "RTRning Quyidagi raqamlangan ko‘z olmasi kesimi rasmini daftaringizga chizing va 1–16 raqamlar bilan belgilangan tuzilmalarning nomini yozing. Har bir tuzilmaning bitta asosiy vazifasini ko‘rsating.", "check": "Barcha 16 tuzilma to‘g‘ri nomlangan va vazifasi ko‘rsatilgan bo‘lsa – “a’lo”.", "img": "02_koz_kesimi_raqamli.png", "answers": ["Shox parda", "Limb", "Oldingi kamera", "Rangdor parda", "Qorachiq", "Kiprikli tana", "Sinn boylamlari", "Gavhar", "Sklera (oqsil parda)", "Xususiy tomirli parda", "To‘r parda", "Shishasimon tana", "Sariq dog‘", "Ko‘ruv nervi diski", "Ko‘ruv nervi", "To‘g‘ri muskul"]}, {"title": "2-topshiriq. Ko‘rish o‘tkirligini aniqlash (rolli o‘yin)", "text": "Juftlikda ishlang: biri “hamshira”, biri “bemor”. Sivtsev–Golovin jadvali yordamida 5 m masofadan har bir ko‘zning ko‘rish o‘tkirligini tekshiring va natijani tibbiy hujjat shaklida yozing (Visus OD = …; Visus OS = …). So‘ng rollarni almashtiring.", "check": "Tekshiruv algoritmi (masofa, yoritish, ko‘zni bosmasdan yopish, har bir belgiga 2–3 soniya, yozuv shakli) to‘liq bajarilishi baholanadi."}, {"title": "3-topshiriq. Vaziyatli masala", "text": "Poliklinikaga 45 yoshli haydovchi murojaat qildi. U so‘nggi oylarda kechqurun mashina haydaganda yo‘lni yomon ko‘rayotganini, kunduzi esa ko‘rishi yaxshi ekanini aytadi. Ovqatlanishi bir xil, sabzavot va sut mahsulotlarini kam iste’mol qiladi. Savollar: 1) Bemorda qaysi ko‘rish funksiyasi buzilgan? 2) Bu holat qanday ataladi? 3) Qanday sabab bo‘lishi mumkin? 4) Hamshira qanday maslahatlar beradi?", "check": "Javob: qorong‘ilik adaptatsiyasi (yorug‘lik sezish) buzilgan; gemeralopiya (“tovuq ko‘rlik”); ehtimoliy sabab – A vitamini yetishmovchiligi; maslahat – oftalmologga yo‘llash, A vitaminiga boy mahsulotlar (sabzi, jigar, sariyog‘, tuxum sarig‘i), kechasi haydashni vaqtincha cheklash."}, {"title": "4-topshiriq. Vaziyatli masala", "text": "Hamshira maktabda profilaktik ko‘rik o‘tkazmoqda. 9 yoshli o‘g‘il bola Sivtsev jadvalining birinchi qatorini ham 5 m dan o‘qiy olmadi, lekin 3 m ga yaqinlashganda o‘qidi. Savollar: 1) Bolaning ko‘rish o‘tkirligini Snellen formulasi bo‘yicha hisoblang. 2) Natija qanday yoziladi? 3) Hamshiraning keyingi harakatlari qanday?", "check": "Javob: V = d/D = 3/50 = 0,06; Visus = 0,06; ota-onaga xabar berish va oftalmolog ko‘rigiga yo‘llash, tibbiy kartaga qayd etish."}, {"title": "5-topshiriq. Mashq: Snellen formulasi", "text": "Bemor jadvalning birinchi qatorini (D = 50 m) quyidagi masofalardan o‘qidi. Ko‘rish o‘tkirligini hisoblang: a) 4 m; b) 1 m; c) 0,5 m; d) 2,5 m.", "check": "Javoblar: a) 0,08; b) 0,02; c) 0,01; d) 0,05."}], "matching": [["Kolbachalar", "Kunduzgi va rangli ko‘rishni ta’minlovchi fotoretseptorlar"], ["Tayoqchalar", "G‘ira-shira va qorong‘ida ko‘rishni ta’minlovchi fotoretseptorlar"], ["Qorachiq", "Rangdor parda markazidagi, yorug‘lik miqdorini boshqaruvchi teshik"], ["Sklera", "Fibroz pardaning oq, noshaffof qismi"], ["Gavhar", "Ikki tomoni qavariq, tiniq, elastik linza"], ["Limb", "Shox pardaning skleraga o‘tish joyi"], ["Visus", "Ko‘rish o‘tkirligi"], ["Fuziya", "Ikki ko‘zdagi tasvirlarning yagona tasvirga qo‘shilishi"]], "structure": [["Tashkiliy qism", "5 daq.", "Salomlashish, davomat"], ["Tayanch bilimlarni faollashtirish", "5 daq.", "Tezkor savol-javob"], ["Yangi mavzu bayoni", "35 daq.", "Taqdimot, video, animatsiya, plakat"], ["Tizimlashtirish", "7 daq.", "Klaster"], ["Mustahkamlash", "15 daq.", "“Galereya bo‘ylab sayohat”, kichik guruhlar"], ["Nazorat va baholash", "10 daq.", "Test, moslashtirish mashqi"], ["Yakun, uyga vazifa", "3 daq.", "Insert usulida o‘qish"]], "literature": ["Yuldasheva F. S., Yusupova M. S., Aripova S. M. Ko‘z kasalliklari. – Toshkent: Cho‘lpon nomidagi NMIU, 2007.", "Po‘latova Sh. A., Aripova G. S., Mirzajonova G. X. va boshq. Kattalarda hamshiralik parvarishi. II qism. – Toshkent, 2012.", "Bikbov M. M. va boshq. Oftalmologiya: darslik (rus tilida). – Moskva: GEOTAR-Media, 2019.", "World Health Organization. World report on vision. – Geneva: WHO, 2019.", "Abu Ali ibn Sino. Tib qonunlari. III kitob. – Toshkent: Fan, 1993 (o‘zbek tilidagi nashr)."], "handouts": [{"title": "Tarqatma material: ko‘z pardalari", "rows": [["Parda", "Qismlari", "Asosiy vazifasi"], ["Tashqi (fibroz)", "Shox parda (1/6), sklera (5/6)", "Shakl berish, himoya; shox parda – nur o‘tkazish va sindirish"], ["O‘rta (tomirli)", "Rangdor parda, kiprikli tana, xususiy tomirli parda", "Oziqlantirish, yorug‘likni boshqarish, ko‘z ichi suyuqligi, akkomodatsiya"], ["Ichki (to‘r)", "Optik qism, ko‘rmaydigan qism", "Yorug‘likni qabul qilib, nerv impulsiga aylantirish"]]}], "algorithms": [{"title": "Ko‘rish o‘tkirligini aniqlash", "tools": "Sivtsev–Golovin jadvali, Rot apparati, ko‘rsatgich, to‘siq", "steps": ["Bemorga tekshiruv maqsadini tushuntiring va uni jadvaldan 5 m masofaga o‘tqazing.", "Rot apparatini yoqing: jadval bir tekis yoritilgan bo‘lishi kerak.", "Chap ko‘zni to‘siq bilan bosmasdan yoping va avval o‘ng ko‘zni tekshiring.", "Ko‘rsatgich bilan harflarni yuqori qatordan boshlab ko‘rsating, har bir belgiga 2–3 soniya bering.", "Bemor xatosiz o‘qigan eng pastki qatorni aniqlang (0,3–0,6 qatorlarda bitta, 0,7–1,0 qatorlarda ikkita xatoga yo‘l qo‘yiladi).", "Xuddi shu tartibda chap ko‘zni tekshiring.", "Natijani yozing: Visus OD = …; Visus OS = ….", "To‘siq va ko‘rsatgichni dezinfeksiya qiling."]}], "interactive": ["ray", "pupil", "blind", "snellen"], "type": "Nazariy", "lecture": "<section class=\"lec-sec\" id=\"lec-1\"><h2>1. “Oftalmologiya” fani haqida tushuncha va uning tibbiyot fanlari orasidagi o‘rni</h2><p>Oftalmologiya (yunoncha ophthalmos – ko‘z, logos – ta’limot, fan) – ko‘ruv a’zosining tuzilishi, fiziologiyasi, kasalliklarining kelib chiqish sabablari, rivojlanishi, belgilari, tashxisi, davolash va oldini olish usullarini o‘rganadigan klinik tibbiyot fanidir. Oftalmologiyani qisqacha “ko‘z kasalliklari to‘g‘risidagi fan” deb ham atashadi. Ko‘z kasalliklari bilan shug‘ullanuvchi shifokor oftalmolog (okulist), ko‘z bo‘limi yoki kabinetida ishlovchi hamshira esa oftalmologik hamshira deyiladi.</p><p>Inson tashqi muhit to‘g‘risidagi ma’lumotlarning 80–90 foizini ko‘ruv a’zosi orqali qabul qiladi. Ko‘rish qobiliyati odamning o‘qishi, kasb egallashi, mehnat qilishi, transport boshqarishi va jamiyatdagi faol hayoti uchun zarur shartdir. Shu sababli ko‘rishning pasayishi yoki yo‘qolishi nafaqat tibbiy, balki katta ijtimoiy muammo hisoblanadi. Jahon sog‘liqni saqlash tashkilotining ma’lumotlariga ko‘ra, dunyoda kamida 2,2 milliard kishida ko‘rish buzilishi mavjud bo‘lib, ularning deyarli yarmida bu holatning oldini olish yoki uni o‘z vaqtida davolash mumkin edi. Ko‘rlik va zaif ko‘rishning asosiy sabablari – tuzatilmagan refraksiya anomaliyalari (miopiya, gipermetropiya, astigmatizm), katarakta, glaukoma, qandli diabet asoratlari (diabetik retinopatiya) va yoshga bog‘liq makula degeneratsiyasidir.</p><h3>Oftalmologiyaning vazifalari</h3><ul><li>ko‘ruv a’zosining normal tuzilishi va faoliyatini o‘rganish;</li><li>ko‘z kasalliklarining sabablari va rivojlanish mexanizmlarini aniqlash;</li><li>ko‘zni tekshirishning zamonaviy usullarini ishlab chiqish va amaliyotga joriy etish;</li><li>ko‘z kasalliklarini konservativ (dori-darmon, fizioterapiya) va jarrohlik (mikroxirurgiya, lazer) usullari bilan davolash;</li><li>ko‘rlik va zaif ko‘rishning oldini olish, aholi o‘rtasida profilaktik ko‘riklar o‘tkazish;</li><li>ko‘zi ojiz va zaif ko‘ruvchi shaxslarni reabilitatsiya qilish, mehnat qobiliyatini ekspertiza qilish.</li></ul><h3>Oftalmologiyaning bo‘limlari</h3><p>Hozirgi zamon oftalmologiyasi bir nechta mustaqil yo‘nalishlarga bo‘linadi: bolalar oftalmologiyasi, oftalmoxirurgiya (ko‘z mikroxirurgiyasi), lazer oftalmologiyasi, refraksion jarrohlik, glaukomatologiya, kontaktologiya (kontakt linzalar tanlash), neyrooftalmologiya, oftalmoonkologiya, ko‘z travmatologiyasi va oftalmologik ekspertiza. Har bir yo‘nalishda hamshira shifokorning yaqin yordamchisi sifatida ishtirok etadi.</p><h3>Oftalmologiyaning boshqa fanlar bilan bog‘liqligi</h3><p>Ko‘z organizmning ajralmas qismi bo‘lgani uchun ko‘plab umumiy kasalliklar ko‘zda o‘z aksini topadi. Masalan, gipertoniya kasalligida ko‘z tubi tomirlari torayadi va to‘r pardada qon quyilishlar paydo bo‘ladi; qandli diabetda diabetik retinopatiya va katarakta rivojlanadi; buyrak kasalliklari, ateroskleroz, revmatizm, sil, toksoplazmoz, bosh miya o‘smalari va jarohatlari ham ko‘z tubida o‘ziga xos o‘zgarishlar beradi. Shu sababli oftalmolog ko‘pincha terapevt, nevropatolog, endokrinolog, pediatr, otorinolaringolog, stomatolog va neyroxirurg bilan hamkorlikda ishlaydi. Ko‘z tubini tekshirish (oftalmoskopiya) ko‘plab umumiy kasalliklarning tashxisi va kechishini baholashda muhim ahamiyatga ega.</p><p>Oftalmologiya fani normal anatomiya, normal fiziologiya, gistologiya, fizika (optika), lotin tili va tibbiy terminologiya, farmakologiya, mikrobiologiya, terapiya, pediatriya, jarrohlik va hamshiralik ishi asoslari fanlari bilan uzviy bog‘liq. Masalan, ko‘zning nur sindirish tizimini tushunish uchun fizikadan optika qonunlarini, ko‘z kasalliklarida qo‘llaniladigan tomchi dorilarni to‘g‘ri tayyorlash va tomizish uchun esa farmakologiya va hamshiralik manipulyatsiyalarini bilish talab etiladi.</p><h3>Aholiga oftalmologik yordamni tashkil etish</h3><p>Respublikamizda aholiga ko‘z bo‘yicha tibbiy yordam bosqichma-bosqich ko‘rsatiladi. Birlamchi bo‘g‘inda – oilaviy poliklinika va oilaviy shifokor punktlarida ko‘rish o‘tkirligi aniqlanadi, ko‘z ichi bosimi o‘lchanadi, oddiy yallig‘lanish kasalliklari davolanadi, ko‘zga tushgan yot jismlar olinadi va bemorlar zarur hollarda ixtisoslashgan muassasaga yo‘llanadi. Ikkinchi bosqichda tuman (shahar) tibbiyot birlashmalarining ko‘z kabinetlari va bo‘limlari, uchinchi bosqichda esa viloyat ko‘z kasalliklari shifoxonalari hamda respublika ixtisoslashtirilgan markazlari faoliyat ko‘rsatadi. Maktab va maktabgacha ta’lim muassasalarida bolalar har yili ko‘rikdan o‘tkaziladi, 40 yoshdan oshgan barcha shaxslarda glaukomani erta aniqlash maqsadida ko‘z ichi bosimini o‘lchash tavsiya etiladi. Qandli diabet bilan og‘rigan bemorlar yiliga kamida bir marta ko‘z tubi tekshiruvidan o‘tishi lozim. Bu profilaktik tadbirlarni tashkil etish va o‘tkazishda hamshiraning hissasi juda katta.</p><h3>Oftalmologiyada hamshiraning o‘rni</h3><p>Umumiy amaliyot hamshirasi poliklinika, oilaviy shifokor punkti, ko‘z kabineti va statsionarning ko‘z bo‘limida ishlaydi. Uning asosiy vazifalari quyidagilardan iborat: bemorlarni qabul qilish va tekshiruvga tayyorlash; ko‘rish o‘tkirligi, rang ko‘rish va ko‘z ichi bosimini aniqlashda ishtirok etish; shifokor tayinlagan muolajalarni bajarish (kon’yunktiva bo‘shlig‘iga tomchi dori tomizish, malham qo‘yish, ko‘zni yuvish, bog‘lam qo‘yish); operatsiyadan oldin va keyin bemorni parvarish qilish; ko‘zga yot jism tushganda, kuyish va jarohatlarda birinchi yordam ko‘rsatish; aholi o‘rtasida ko‘z gigiyenasi va ko‘rlikning oldini olish bo‘yicha sanitariya-oqartuv ishlarini olib borish. Hamshira aseptika va antiseptika qoidalariga qat’iy rioya qilishi shart, chunki ko‘z infeksiyalari (masalan, adenovirusli kon’yunktivit) asboblar va qo‘l orqali oson yuqadi.</p><p>Xulosa qilib aytganda, oftalmologiya klinik tibbiyotning mustaqil, ijtimoiy ahamiyati juda yuqori bo‘lgan sohasi bo‘lib, uning yutuqlari ko‘p jihatdan malakali o‘rta tibbiyot xodimlarining – hamshiralarning bilimi va mahoratiga bog‘liqdir.</p></section><section class=\"lec-sec\" id=\"lec-2\"><h2>2. Oftalmologiya fanining rivojlanish tarixi</h2><p>Ko‘z kasalliklari haqidagi dastlabki ma’lumotlar eng qadimgi yozma manbalarda uchraydi. Oftalmologiya tarixini shartli ravishda quyidagi davrlarga bo‘lish mumkin: qadimgi dunyo davri, Sharq (o‘rta asrlar) tabobati davri, Yevropa Uyg‘onish davri va yangi davr, hozirgi zamon oftalmologiyasi.</p><h3>Qadimgi dunyo davri</h3><figure><img src=\"mavzular/n1/didaktik/07_tarix_vaqt_chizigi.png\" alt=\"Oftalmologiya rivojining asosiy bosqichlari\" loading=\"lazy\" data-zoom><figcaption>Oftalmologiya rivojining asosiy bosqichlari</figcaption></figure><p>Qadimgi Misrda miloddan avvalgi XVI asrga oid Ebers papirusida ko‘z kasalliklari va ularni davolash uchun ishlatilgan ko‘plab retseptlar keltirilgan. Bobilda podsho Hammurapi qonunlarida (miloddan avvalgi XVIII asr) ko‘z operatsiyasi muvaffaqiyatli o‘tsa tabibga to‘lanadigan haq va muvaffaqiyatsiz bo‘lsa unga beriladigan jazo belgilangan. Qadimgi Hindistonda tabib Sushruta katarakta (ko‘z gavharining xiralashishi)ni gavharni ko‘z ichiga tushirib yuborish usuli bilan operatsiya qilgan va 70 dan ortiq ko‘z kasalligini tasvirlagan.</p><p>Qadimgi Yunonistonda Gippokrat ko‘z kasalliklarining bir qancha turlarini (kon’yunktivit, trixiaz, katarakta) tasvirlagan. Rimlik olim Aul Korneliy Sels (I asr) katarakta operatsiyasini batafsil bayon qilgan, Galen (II asr) esa ko‘z anatomiyasi va ko‘ruv nervi haqida muhim ma’lumotlar qoldirgan. Ammo bu davrda ko‘zning nur sindirish vazifasi noto‘g‘ri tushunilgan: tasvirni ko‘z gavhari qabul qiladi, deb hisoblangan.</p><h3>Sharq tabobati davri (IX–XIII asrlar)</h3><p>O‘rta asrlarda oftalmologiya Sharq mamlakatlarida, jumladan, Markaziy Osiyoda yuqori darajada rivojlandi. Bu davrda ko‘z tabiblari “kahhol” deb atalgan. Hunayn ibn Ishoq (IX asr) “Ko‘z haqida o‘n maqola” asarini yozdi – bu oftalmologiyaga oid eng qadimgi tizimli darsliklardan biri hisoblanadi. Ali ibn Iso al-Kahhol (X–XI asrlar) 130 ga yaqin ko‘z kasalligini tasvirlagan “Ko‘z tabiblari uchun eslatma” kitobini yaratdi. Ammor al-Mavsiliy kataraktani ichi bo‘sh ignasimon asbob yordamida so‘rib olish usulini taklif qildi. Ibn al-Haysam (Alhazen) “Optika kitobi”da yorug‘lik ko‘zga tashqaridan tushishini va ko‘rish jarayonini ilmiy asosda tushuntirdi.</p><p>Buyuk vatandoshimiz Abu Ali ibn Sino (980–1037) “Tib qonunlari” asarining uchinchi kitobida ko‘zning anatomiyasi, fiziologiyasi va kasalliklariga keng o‘rin ajratgan. U ko‘zning olti tashqi muskulini, ko‘ruv nervi va uning kesishmasini tasvirlagan, ko‘z kasalliklarini davolash uchun ko‘plab dori-darmon va jarrohlik usullarini bayon qilgan, ko‘z gigiyenasiga katta e’tibor bergan. Ibn Sino traxoma, katarakta, qovoq kasalliklari va “tungi ko‘rlik” haqida qimmatli ma’lumotlar qoldirgan. Uning asarlari lotin tiliga tarjima qilinib, bir necha asr davomida Yevropa universitetlarida asosiy darslik bo‘lib xizmat qilgan.</p><h3>Yevropa Uyg‘onish davri va yangi davr (XVI–XIX asrlar)</h3><p>1604-yilda nemis olimi Iogann Kepler tasvir to‘r pardada hosil bo‘lishini isbotladi, gavhar esa nur sindiruvchi linza vazifasini bajarishini ko‘rsatdi. 1748-yilda fransuz jarrohi Jak Daviel kataraktani ko‘zdan chiqarib olish (ekstraksiya) operatsiyasini birinchi bo‘lib amalga oshirdi. XIX asrda oftalmologiya mustaqil fan sifatida shakllandi: 1851-yilda German Gelmgols ko‘z ko‘zgusi – oftalmoskopni ixtiro qildi va ko‘z tubini tirik odamda ko‘rish imkoniyati paydo bo‘ldi. Gollandiyalik olim Frans Donders ko‘zning refraksiyasi va akkomodatsiyasi haqidagi ta’limotni yaratdi, German Snellen esa 1862-yilda ko‘rish o‘tkirligini aniqlash jadvalini taklif qildi. Albrext fon Grefe glaukomani jarrohlik yo‘li bilan davolash (iridektomiya) usulini ishlab chiqdi. 1911-yilda shved olimi Allvar Gullstrand ko‘zning optik tizimini o‘rgangani uchun Nobel mukofotiga sazovor bo‘ldi; u yorituvchi tirqishli lampa – biomikroskopni ham ixtiro qilgan.</p><h3>XX asr va hozirgi zamon oftalmologiyasi</h3><p>XX asrda oftalmologiya jadal rivojlandi. Akademik V. P. Filatov shox pardani ko‘chirib o‘tkazish (keratoplastika) usulini takomillashtirdi va to‘qima terapiyasi ta’limotini yaratdi. Akademik S. N. Fyodorov ko‘z mikroxirurgiyasi rivojiga katta hissa qo‘shib, sun’iy gavhar (intraokulyar linza) qo‘yish va miopiyani jarrohlik yo‘li bilan tuzatish usullarini keng joriy etdi. XX asrning ikkinchi yarmida lazer texnologiyalari, ultratovush tekshiruvi, kompyuter perimetriyasi, optik kogerent tomografiya (OKT) kabi zamonaviy tashxis usullari amaliyotga kirdi.</p><p>O‘zbekistonda oftalmologiyaning ilmiy asosda rivojlanishi XX asr boshlarida Toshkentda tibbiyot fakulteti va ko‘z kasalliklari kafedrasi tashkil etilishi bilan boshlandi. O‘sha davrda aholi orasida keng tarqalgan traxoma kasalligiga qarshi maxsus traxoma punktlari va dispanserlar tarmog‘i tuzildi, natijada traxoma ommaviy kasallik sifatida tugatildi. Hozirgi kunda respublikamizda Respublika ixtisoslashtirilgan ko‘z mikroxirurgiyasi ilmiy-amaliy tibbiyot markazi va uning hududiy filiallari, viloyat ko‘z kasalliklari shifoxonalari faoliyat ko‘rsatmoqda. Kataraktani fakoemulsifikatsiya usulida olib tashlash, glaukoma va to‘r pardaning lazer bilan davolash, refraksion lazer operatsiyalari muvaffaqiyatli bajarilmoqda.</p><p>Oftalmologiya tarixini bilish hamshiraga bugungi zamonaviy tekshirish va davolash usullarining kelib chiqishini tushunishga, buyuk ajdodlarimiz merosi bilan faxrlanishga va kasbiga mas’uliyat bilan yondashishga yordam beradi.</p><div class=\"tbl\"><table><thead><tr><th>Davr / sana</th><th>Olim yoki manba</th><th>Hissasi</th></tr></thead><tbody><tr><td>Mil. avv. XVI asr</td><td>Ebers papirusi (Misr)</td><td>Ko‘z kasalliklarini davolash retseptlari</td></tr><tr><td>Mil. avv. VI asr (taxm.)</td><td>Sushruta (Hindiston)</td><td>Katarakta operatsiyasi, 70 dan ortiq ko‘z kasalligi tasviri</td></tr><tr><td>IX asr</td><td>Hunayn ibn Ishoq</td><td>“Ko‘z haqida o‘n maqola” darsligi</td></tr><tr><td>X–XI asrlar</td><td>Abu Ali ibn Sino</td><td>“Tib qonunlari”ning 3-kitobida ko‘z anatomiyasi va kasalliklari</td></tr><tr><td>1604-yil</td><td>I. Kepler</td><td>Tasvir to‘r pardada hosil bo‘lishini isbotladi</td></tr><tr><td>1748-yil</td><td>J. Daviel</td><td>Katarakta ekstraksiyasi operatsiyasi</td></tr><tr><td>1851-yil</td><td>G. Gelmgols</td><td>Oftalmoskopni ixtiro qildi</td></tr><tr><td>1862-yil</td><td>G. Snellen</td><td>Ko‘rish o‘tkirligini aniqlash jadvali</td></tr><tr><td>1911-yil</td><td>A. Gullstrand</td><td>Ko‘z optikasi, tirqishli lampa; Nobel mukofoti</td></tr><tr><td>XX asr</td><td>V. P. Filatov, S. N. Fyodorov</td><td>Keratoplastika, ko‘z mikroxirurgiyasi, sun’iy gavhar</td></tr></tbody></table></div></section><section class=\"lec-sec\" id=\"lec-3\"><h2>3. Ko‘ruv organi anatomiyasi</h2><p>Ko‘ruv organi (organum visus) ko‘ruv analizatorining periferik qismi hisoblanadi. I. P. Pavlov ta’limotiga ko‘ra, har bir analizator uch qismdan iborat. Ko‘ruv analizatori tarkibiga quyidagilar kiradi:</p><ul><li>periferik (qabul qiluvchi) qism – ko‘z olmasi va uning to‘r pardasidagi yorug‘lik sezuvchi hujayralar;</li><li>o‘tkazuvchi yo‘llar – ko‘ruv nervi, ko‘ruv nervlarining kesishmasi (xiazma), ko‘ruv yo‘llari (traktlar), tashqi tizzasimon tanalar va ko‘ruv nurlanishi;</li><li>markaziy (po‘stloq) qism – bosh miya katta yarim sharlarining ensa bo‘lagidagi shporasimon egat atrofida joylashgan ko‘rish markazi.</li></ul><p>Ko‘rish a’zosi anatomik jihatdan ko‘z olmasi (bulbus oculi) va ko‘zning yordamchi apparatidan iborat. Yordamchi apparatga ko‘z kosasi (orbita), qovoqlar, kon’yunktiva, ko‘z yoshi a’zolari va ko‘z olmasini harakatlantiruvchi muskullar kiradi.</p><figure><img src=\"mavzular/n1/didaktik/03_koruv_yoli.png\" alt=\"1-rasm. Ko‘ruv analizatorining tuzilishi\" loading=\"lazy\" data-zoom><figcaption>1-rasm. Ko‘ruv analizatorining tuzilishi</figcaption></figure><h3>Ko‘z olmasi</h3><p>Ko‘z olmasi sharsimon shaklga ega bo‘lib, ko‘z kosasining old qismida joylashgan. Katta yoshli odamda uning old-orqa o‘lchami (o‘qi) o‘rtacha 24 mm, ko‘ndalang o‘lchami 23,5 mm, vertikal o‘lchami 23 mm, massasi 7–8 g ni tashkil etadi. Yangi tug‘ilgan chaqaloqda ko‘z o‘qi taxminan 16–18 mm bo‘ladi. Ko‘z olmasining old qismidagi eng bo‘rtib chiqqan nuqtasi old qutb, orqa qismidagisi esa orqa qutb deb ataladi. Ko‘z olmasi devori uchta pardadan – tashqi (fibroz), o‘rta (tomirli) va ichki (to‘r) pardalardan tuzilgan, uning ichi esa nur o‘tkazuvchi tiniq muhitlar bilan to‘lgan.</p><h3>Tashqi – fibroz parda</h3><p>Fibroz parda zich biriktiruvchi to‘qimadan iborat bo‘lib, ko‘zga shakl beradi va ichki tuzilmalarni himoya qiladi. U ikki qismdan – oldingi tiniq shox parda va orqadagi noshaffof oqsil pardadan tashkil topgan.</p><figure><img src=\"mavzular/n1/didaktik/01_koz_kesimi_belgili.png\" alt=\"2-rasm. Ko‘z olmasining gorizontal kesimi\" loading=\"lazy\" data-zoom><figcaption>2-rasm. Ko‘z olmasining gorizontal kesimi</figcaption></figure><p>Shox parda (cornea) fibroz pardaning 1/6 qismini egallaydi. U tiniq, yaltiroq, silliq, sferik va o‘ta sezgir. Katta yoshdagi odamda shox pardaning gorizontal diametri 11–12 mm, yangi tug‘ilgan chaqaloqda esa 9–10 mm atrofida bo‘ladi. Qalinligi markazida 0,5–0,6 mm, chekkasida 1 mm gacha. Shox parda besh qavatdan iborat: oldingi epiteliy, Boumen membranasi, xususiy modda (stroma), Descemet membranasi va orqa epiteliy (endoteliy). Shox pardada qon tomirlari bo‘lmaydi, lekin u uch shoxli nervning tolalariga juda boy, shuning uchun uning yuzasiga eng kichik yot jism tushsa ham kuchli og‘riq, ko‘z yoshlanishi va qovoqlarning qisilishi (himoya refleksi) yuzaga keladi. Shox parda ko‘z ichi suyuqligi, ko‘z yoshi pardasi va limb atrofidagi qon tomirlar to‘ri hisobiga oziqlanadi. Uning asosiy vazifasi – nurni o‘tkazish va sindirish (sindirish kuchi 40–43 dioptriya).</p><p>Oqsil parda (sclera) fibroz pardaning 5/6 qismini tashkil etadi. U oq rangli, noshaffof, zich kollagen tolalardan iborat, qalinligi 0,3–1 mm. Bolalarda sklera yupqa bo‘lgani uchun ko‘kimtir tusda, keksalarda esa sarg‘ishroq ko‘rinadi. Orqa qutbda sklera g‘alvirsimon plastinkani hosil qiladi, uning teshiklaridan ko‘ruv nervi tolalari chiqib ketadi. Skleraga ko‘zni harakatlantiruvchi muskullar birikadi. Shox pardaning skleraga o‘tish joyi limb deb ataladi (kengligi taxminan 1 mm). Sklera ko‘zga shakl beradi va ichki pardalarni himoya qiladi.</p><h3>O‘rta – tomirli parda</h3><p>Tomirli parda qon tomirlariga boy bo‘lib, ko‘zning ichki tuzilmalarini oziqlantiradi. U uch qismdan iborat: rangdor parda, kiprikli (kipriksimon) tana va xususiy tomirli parda.</p><p>Rangdor parda (iris) tomirli pardaning oldingi qismi bo‘lib, shox parda orqasida vertikal holatda joylashgan. Uning rangi tarkibidagi pigment miqdoriga bog‘liq (ko‘k, kulrang, yashil, jigarrang). Rangdor pardaning markazida yumaloq teshik – qorachiq (pupilla) bor, normada uning diametri 3–4 mm. Rangdor pardada ikki silliq muskul joylashgan: qorachiqni toraytiruvchi muskul (ko‘zni harakatlantiruvchi nervning parasimpatik tolalari innervatsiya qiladi) va qorachiqni kengaytiruvchi muskul (simpatik nerv tolalari innervatsiya qiladi). Qorachiq yorug‘likda torayadi, qorong‘ilikda kengayadi, ya’ni u fotoapparatning diafragmasi kabi ko‘zga tushadigan yorug‘lik miqdorini boshqaradi.</p><p>Kiprikli tana (corpus ciliare) rangdor parda bilan xususiy tomirli parda o‘rtasida halqa shaklida joylashgan. Uning o‘simtalari ko‘z ichi suyuqligini ishlab chiqaradi. Kiprikli tanadagi muskul Sinn boylamlari orqali gavharga ta’sir etib, uning egriligini o‘zgartiradi va akkomodatsiyani – ko‘zning turli masofadagi narsalarni aniq ko‘rishga moslashishini ta’minlaydi. Kiprikli tana yallig‘langanda (iridotsiklit) ko‘zni bosib ko‘rganda og‘riq paydo bo‘ladi.</p><p>Xususiy tomirli parda (chorioidea) tomirli pardaning orqa, eng katta qismi bo‘lib, sklera bilan to‘r parda o‘rtasida joylashgan. U asosan qon tomirlardan tuzilgan va to‘r pardaning tashqi qavatlarini, ayniqsa yorug‘lik sezuvchi hujayralarni oziqlantiradi.</p><h3>Ichki – to‘r parda</h3><p>To‘r parda (retina) ko‘z olmasining eng ichki, yupqa, tiniq pardasi bo‘lib, yorug‘lik ta’sirini nerv impulsiga aylantiradi. U ikki qismdan iborat: optik (ko‘ruvchi) qism – to‘r pardaning orqadagi 2/3 qismi, va ko‘rmaydigan qism – kiprikli tana va rangdor pardaning orqa yuzasini qoplab turadi. Optik qism mikroskopik jihatdan 10 qavatdan tuzilgan. Uning eng muhim hujayralari – yorug‘lik sezuvchi fotoretseptorlar: tayoqchalar va kolbachalar.</p><ul><li>Tayoqchalar soni taxminan 120–130 million, ular asosan to‘r pardaning periferik qismida joylashgan; kuchsiz yorug‘likni sezadi va g‘ira-shira hamda qorong‘ida ko‘rishni ta’minlaydi. Tayoqchalarda ko‘ruv purpuri – rodopsin bor, uning hosil bo‘lishi uchun A vitamini zarur.</li><li>Kolbachalar soni taxminan 6–7 million, ular asosan markazda – sariq dog‘da to‘plangan; kunduzgi yorug‘likda ishlaydi, narsalarning mayda qismlarini va rangini farqlashni ta’minlaydi.</li></ul><p>Ko‘z tubida ikki muhim tuzilma ko‘rinadi. Sariq dog‘ (macula lutea) – to‘r pardaning markazidagi taxminan 5 mm li soha bo‘lib, uning o‘rtasidagi markaziy chuqurcha (fovea) faqat kolbachalardan iborat va eng aniq ko‘rish nuqtasi hisoblanadi. Ko‘ruv nervi diski (so‘rg‘ichi) – ko‘ruv nervi tolalarining ko‘z olmasidan chiqish joyi, diametri 1,5–1,8 mm. Bu sohada fotoretseptorlar bo‘lmagani uchun u ko‘rmaydi va “ko‘r dog‘” (Mariott dog‘i) deb ataladi. Ko‘ruv nervi diskining markazidan to‘r pardaning markaziy arteriyasi va venasi chiqadi.</p><h3>Ko‘zning ichki tiniq muhitlari</h3><p>Ko‘z olmasining ichida nur o‘tkazuvchi va nur sindiruvchi tiniq muhitlar joylashgan: ko‘z ichi suyuqligi, gavhar va shishasimon tana. Shox parda bilan birgalikda ular ko‘zning optik tizimini hosil qiladi.</p><ul><li>Ko‘z ichi suyuqligi kiprikli tanada ishlab chiqariladi va ko‘zning oldingi kamerasi (shox parda bilan rangdor parda orasidagi bo‘shliq, chuqurligi markazda 3–3,5 mm) hamda orqa kamerasini (rangdor parda bilan gavhar orasidagi bo‘shliq) to‘ldiradi. U shox parda va gavharni oziqlantiradi. Suyuqlik asosan oldingi kamera burchagi va Shlemm kanali orqali vena tizimiga chiqib ketadi. Suyuqlikning ishlab chiqarilishi va chiqib ketishi orasidagi muvozanat ko‘z ichi bosimini belgilaydi; uning normasi Maklakov tonometri bo‘yicha 18–26 mm sim. ust. Ushbu muvozanat buzilsa, glaukoma rivojlanishi mumkin.</li><li>Gavhar (lens) – ikki tomoni qavariq, tiniq, elastik linza. Diametri 9–10 mm, qalinligi 3,5–5 mm, sindirish kuchi taxminan 18–20 dioptriya. Gavharda qon tomirlari va nervlar yo‘q, u kiprikli tanaga Sinn boylamlari yordamida osilib turadi. Yosh o‘tishi bilan gavhar elastikligini yo‘qotadi (presbiopiya), uning xiralashishi esa katarakta deb ataladi.</li><li>Shishasimon tana (corpus vitreum) – gavhar orqasida joylashgan tiniq, iviqsimon modda; ko‘z olmasi hajmining taxminan 2/3 qismini (4 ml ga yaqin) egallaydi, 98–99 foizi suvdan iborat. U ko‘zning shaklini saqlaydi va to‘r pardani tomirli pardaga bosib turadi.</li></ul><h3>Ko‘zning yordamchi apparati</h3><p>Ko‘z kosasi (orbita) – yetti suyakdan (peshona, yonoq, yuqori jag‘, g‘alvirsimon, ponasimon, ko‘z yoshi va tanglay suyaklari) hosil bo‘lgan to‘rt qirrali piramida shaklidagi bo‘shliq, chuqurligi 4–5 sm. Unda ko‘z olmasi, muskullar, nervlar, qon tomirlar va yog‘ to‘qimasi joylashgan. Ko‘z kosasi ko‘zni tashqi ta’sirlardan himoya qiladi.</p><p>Qovoqlar (palpebrae) – yuqori va pastki teri-muskul burmalari bo‘lib, ko‘zni yorug‘lik, chang va shikastlardan himoya qiladi, ko‘z pirpiratish orqali ko‘z yoshini shox parda yuzasiga bir tekis yoyadi. Qovoq terisi juda yupqa va teri osti kletchatkasi bo‘sh bo‘lgani uchun yallig‘lanishda va jarohatda qovoqlar tez shishadi. Qovoq tarkibida ko‘zning aylana muskuli (yuz nervi innervatsiya qiladi), yuqori qovoqni ko‘taruvchi muskul (ko‘zni harakatlantiruvchi nerv innervatsiya qiladi), tog‘aysimon plastinka va uning ichidagi meybomiy bezlari bor. Qovoqlarning chetida kipriklar o‘sadi, ularning ildizida yog‘ va ter bezlari joylashgan. Qovoqlar orasidagi tirqish ko‘z tirqishi deb ataladi.</p><p>Kon’yunktiva (shilliq parda) – qovoqlarning ichki yuzasini va ko‘z olmasining old qismini (shox pardagacha) qoplab turuvchi yupqa, tiniq shilliq parda. Uning qovoq kon’yunktivasi, o‘tish burmalari va ko‘z olmasi kon’yunktivasi qismlari farqlanadi. Qovoq kon’yunktivasi bilan ko‘z olmasi kon’yunktivasi orasidagi yopiq bo‘shliq kon’yunktiva bo‘shlig‘i deyiladi – hamshira tomchi dori va malhamni aynan shu bo‘shliqqa, asosan pastki o‘tish burmasiga yuboradi.</p><p>Ko‘z yoshi a’zolari ko‘z yoshi ishlab chiqaruvchi va uni o‘tkazuvchi qismlardan iborat. Ko‘z yoshi bezi ko‘z kosasining yuqori-tashqi burchagida joylashgan. Ko‘z yoshi shox parda yuzasini namlab, oziqlantiradi, mikroblardan tozalaydi (tarkibida lizotsim bor) va ko‘zning ichki burchagidagi ko‘z yoshi ko‘lchasiga to‘planadi. So‘ngra u yuqori va pastki ko‘z yoshi nuqtalari, ko‘z yoshi naychalari, ko‘z yoshi xaltasi va burun-ko‘z yoshi kanali orqali burunning pastki yo‘liga oqib tushadi. Bir kecha-kunduzda normada 0,5–1 ml ko‘z yoshi ajraladi.</p><p>Ko‘z olmasini harakatlantiruvchi muskullar oltita: to‘rtta to‘g‘ri (yuqori, pastki, ichki, tashqi) va ikkita qiyshiq (yuqori va pastki) muskul. Ular ko‘z olmasini barcha yo‘nalishlarda harakatlantiradi va ikki ko‘zning birgalikdagi muvofiq harakatini ta’minlaydi. Yuqori qiyshiq muskulni g‘altak nervi (IV juft), tashqi to‘g‘ri muskulni uzoqlashtiruvchi nerv (VI juft), qolgan muskullarni ko‘zni harakatlantiruvchi nerv (III juft) innervatsiya qiladi. Muskullar faoliyati buzilganda g‘ilaylik va ko‘zda ikkilanib ko‘rish paydo bo‘ladi.</p><p>Ko‘z va uning yordamchi apparati asosan ichki uyqu arteriyasining tarmog‘i – ko‘z arteriyasi orqali qon bilan ta’minlanadi. Venoz qon ko‘z venalari orqali g‘orsimon sinusga quyiladi; yuz venalari bilan bog‘lanishi sababli yuzdagi yiringli jarayonlar (masalan, chipqonni siqish) infeksiyaning miyaga tarqalishiga olib kelishi mumkin. Hamshira buni bemorlarga albatta tushuntirishi lozim.</p><div class=\"tbl\"><table><thead><tr><th>Parda</th><th>Qismlari</th><th>Asosiy vazifasi</th></tr></thead><tbody><tr><td>Tashqi (fibroz)</td><td>Shox parda (1/6), oqsil parda – sklera (5/6)</td><td>Shakl berish, himoya, nur o‘tkazish va sindirish (shox parda)</td></tr><tr><td>O‘rta (tomirli)</td><td>Rangdor parda, kiprikli tana, xususiy tomirli parda</td><td>Oziqlantirish, yorug‘lik miqdorini boshqarish, ko‘z ichi suyuqligi ishlab chiqarish, akkomodatsiya</td></tr><tr><td>Ichki (to‘r)</td><td>Optik qism, ko‘rmaydigan qism</td><td>Yorug‘likni qabul qilish va nerv impulsiga aylantirish</td></tr></tbody></table></div></section><section class=\"lec-sec\" id=\"lec-4\"><h2>4. Ko‘ruv organining faoliyati (ko‘rish funksiyalari)</h2><p>Ko‘rish jarayoni quyidagicha amalga oshadi: narsadan qaytgan nurlar shox parda, oldingi kamera suyuqligi, qorachiq, gavhar va shishasimon tanadan o‘tib sinadi va to‘r pardaga, aniqrog‘i sariq dog‘ga, kichraytirilgan va teskari tasvir holida tushadi. Fotoretseptorlarda kimyoviy reaksiya natijasida nerv impulsi hosil bo‘ladi va u ko‘ruv yo‘llari orqali bosh miya po‘stlog‘ining ensa bo‘lagiga yetib boradi. Ko‘rish markazida tasvir tahlil qilinadi va biz narsani to‘g‘ri holatda, rangli va hajmli ko‘ramiz.</p><p>Ko‘zning asosiy ko‘rish funksiyalari beshta: markaziy ko‘rish, periferik ko‘rish, rang ko‘rish, yorug‘lik sezish va binokulyar ko‘rish. Ularni tekshirishda hamshira faol ishtirok etadi.</p><h3>Markaziy ko‘rish (ko‘rish o‘tkirligi)</h3><p>Markaziy ko‘rish sariq dog‘ning markaziy chuqurchasidagi kolbachalar faoliyati bilan bog‘liq bo‘lib, narsalarning shakli va mayda qismlarini aniq farqlashni ta’minlaydi. Uning miqdoriy ko‘rsatkichi ko‘rish o‘tkirligi (visus) deb ataladi – ko‘zning ikki nuqtani alohida-alohida ko‘ra olish qobiliyati. Normal ko‘rish o‘tkirligi 1,0 (100 foiz) ga teng.</p><p>Ko‘rish o‘tkirligi Sivtsev–Golovin jadvali yordamida 5 metr masofadan tekshiriladi. Jadval 12 qatordan iborat bo‘lib, harflar yuqoridan pastga kichrayib boradi; har bir qator yonida ko‘rish o‘tkirligi (V) ko‘rsatilgan (0,1 dan 2,0 gacha). Maktabgacha yoshdagi bolalarni tekshirish uchun rasmli Orlova jadvali ishlatiladi. Jadval Rot apparatida bir tekis yoritilgan bo‘lishi kerak (taxminan 700 lyuks).</p><p>Tekshirish tartibi: bemor jadvaldan 5 m masofada o‘tiradi; har bir ko‘z alohida tekshiriladi – avval o‘ng (OD), keyin chap (OS) ko‘z; tekshirilmayotgan ko‘z maxsus to‘siq (shitok) bilan bosilmasdan yopiladi; hamshira ko‘rsatgich bilan harflarni yuqori qatordan boshlab ko‘rsatadi, har bir belgini o‘qish uchun 2–3 soniya beriladi. Ko‘rish o‘tkirligi bemor xatosiz o‘qiy olgan eng pastki qatorga ko‘ra aniqlanadi (0,3–0,6 qatorlarda bitta, 0,7–1,0 qatorlarda ikkita xatoga yo‘l qo‘yiladi). Natija tibbiy hujjatga quyidagicha yoziladi: Visus OD = 1,0; Visus OS = 0,8.</p><p>Agar bemor 5 m dan eng yuqori qatorni ko‘ra olmasa, u jadvalga yaqinlashtiriladi va Snellen formulasi bo‘yicha hisoblanadi: V = d / D, bu yerda d – bemor eng yuqori qatorni o‘qigan masofa, D – shu qatorni normal ko‘z ko‘radigan masofa (50 m). Masalan, bemor birinchi qatorni 2 m dan o‘qisa, V = 2/50 = 0,04. Ko‘rish o‘tkirligi 0,005 dan past bo‘lsa, yorug‘lik sezishi tekshiriladi. Qorong‘i xonada ko‘zga turli tomondan yorug‘lik tushiriladi: bemor yorug‘likni sezsa va uning yo‘nalishini to‘g‘ri aniqlasa – “yorug‘likni to‘g‘ri proyeksiya bilan sezadi” (1/∞ pr. l. certa), noto‘g‘ri aniqlasa – “noto‘g‘ri proyeksiya bilan” deb yoziladi. Yorug‘likni umuman sezmasa, ko‘rish o‘tkirligi nolga teng (V = 0) – bu mutlaq ko‘rlikdir.</p><h3>Periferik ko‘rish (ko‘ruv maydoni)</h3><figure><img src=\"mavzular/n1/didaktik/04_sivtsev_jadvali.png\" alt=\"3-rasm. Sivtsev–Golovin jadvali\" loading=\"lazy\" data-zoom><figcaption>3-rasm. Sivtsev–Golovin jadvali</figcaption></figure><p>Periferik ko‘rish to‘r pardaning chekka qismlaridagi asosan tayoqchalar faoliyatiga bog‘liq bo‘lib, atrofdagi fazoda mo‘ljal olish, harakatlanuvchi narsalarni sezish va qorong‘ida yo‘l topishni ta’minlaydi. Ko‘z bir nuqtaga qimirlamay qaraganda bir vaqtda ko‘ra oladigan fazo ko‘ruv maydoni deyiladi. Uni taxminiy (nazorat) usulda – shifokor yoki hamshira o‘z ko‘ruv maydoni bilan taqqoslab, yoki aniq usulda – perimetr asbobida (perimetriya) tekshiriladi. Oq rang uchun ko‘ruv maydonining normal chegaralari: tashqi tomonda 90°, pastki tomonda 65°, ichki tomonda 55°, yuqori tomonda 50° atrofida. Ko‘ruv maydonining torayishi glaukoma, to‘r parda va ko‘ruv nervi kasalliklarida, uning ichida ko‘rmaydigan qismlar (skotomalar) paydo bo‘lishi esa to‘r parda va ko‘ruv yo‘llari zararlanganda kuzatiladi. Ko‘ruv maydonining yarmi tushib qolishi gemianopsiya deb ataladi va bosh miya kasalliklarida uchraydi.</p><h3>Rang ko‘rish</h3><p>Rang ko‘rish kolbachalar faoliyati bilan bog‘liq. Yung–Gelmgols uch komponentli nazariyasiga ko‘ra, to‘r pardada uch xil kolbacha mavjud: qizil, yashil va ko‘k ranglarni sezuvchi kolbachalar. Ularning turlicha qo‘zg‘alishi natijasida biz barcha rang va tuslarni ko‘ramiz. Uch rangni ham normal sezish normal trixromaziya deyiladi. Rang ko‘rishning tug‘ma buzilishi ko‘pincha erkaklarda uchraydi va irsiy yo‘l bilan (X xromosoma orqali) beriladi. Qizil rangni sezmaslik – protanopiya, yashil rangni sezmaslik – deyteranopiya, ko‘k rangni sezmaslik – tritanopiya deb ataladi. Qizil va yashil ranglarni farqlay olmaslik ingliz olimi J. Dalton nomi bilan daltonizm deyiladi. Rang ko‘rishning orttirilgan buzilishlari to‘r parda va ko‘ruv nervi kasalliklarida kuzatiladi.</p><p>Rang ko‘rish Rabkin polixromatik jadvallari yordamida tekshiriladi. Jadvallarda bir xil yorqinlikdagi, lekin turli rangdagi doirachalardan raqam yoki shakl tuzilgan bo‘lib, rang ko‘rishi buzilgan odam ularni farqlay olmaydi. Tekshiruv kunduzgi yorug‘likda, 1 m masofada o‘tkaziladi, har bir jadvalni ko‘rish uchun 5–10 soniya beriladi. Rang ko‘rishni tekshirish haydovchilar, uchuvchilar, temir yo‘l va dengiz transporti xodimlari, shifokorlar va boshqa bir qator kasb egalarining kasbiy tanlovida majburiydir.</p><figure><img src=\"mavzular/n1/didaktik/05_koruv_maydoni.png\" alt=\"4-rasm. Ko‘ruv maydonining normal chegaralari\" loading=\"lazy\" data-zoom><figcaption>4-rasm. Ko‘ruv maydonining normal chegaralari</figcaption></figure><h3>Yorug‘lik sezish va qorong‘ilikka moslashish</h3><p>Yorug‘lik sezish – ko‘zning yorug‘likni va uning eng kam miqdorini idrok etish qobiliyati bo‘lib, asosan tayoqchalar faoliyatiga bog‘liq. Ko‘zning turli yoritilganlik darajasiga moslashishi adaptatsiya deyiladi. Yorug‘ joydan qorong‘i joyga o‘tganda ko‘z asta-sekin qorong‘ilikka moslashadi (qorong‘ilik adaptatsiyasi 40–60 daqiqa davom etadi), aksincha, yorug‘likka moslashish tez – 1 daqiqa atrofida yuz beradi. Qorong‘ilik adaptatsiyasining buzilishi gemeralopiya (xalq orasida “tovuq ko‘rlik”) deb ataladi: bemor kunduzi yaxshi ko‘radi, g‘ira-shira va qorong‘ida esa ko‘rmaydi. U ko‘pincha A vitamini yetishmovchiligida (orttirilgan, funksional gemeralopiya) yoki to‘r parda kasalliklarida (tug‘ma, simptomatik gemeralopiya) uchraydi. Funksional gemeralopiyada A vitamini va unga boy mahsulotlar (sabzi, jigar, sariyog‘, tuxum sarig‘i) tavsiya etiladi.</p><figure><img src=\"mavzular/n1/didaktik/06_rang_plastinka.png\" alt=\"5-rasm. Polixromatik plastinka namunasi (raqam: 74)\" loading=\"lazy\" data-zoom><figcaption>5-rasm. Polixromatik plastinka namunasi (raqam: 74)</figcaption></figure><h3>Binokulyar ko‘rish</h3><p>Binokulyar ko‘rish – ikki ko‘z bilan birgalikda ko‘rishda ikkala ko‘zdagi tasvirlarning bosh miya po‘stlog‘ida yagona tasvirga qo‘shilishi (fuziya). Binokulyar ko‘rish narsalarni hajmli (stereoskopik) ko‘rish, ularning chuqurligi va masofasini aniq baholash imkonini beradi. U bolalarda 3–6 yoshgacha shakllanadi. Binokulyar ko‘rish uchun ikki ko‘zning ko‘rish o‘tkirligi yetarli va bir-biriga yaqin bo‘lishi, ko‘z muskullari muvofiq ishlashi kerak. G‘ilaylikda binokulyar ko‘rish buziladi. Binokulyar ko‘rish oddiy sinamalar bilan tekshiriladi: Sokolov sinamasi (“kaftdagi teshik”), qalamlar bilan sinama (bemor qalam uchini ikkinchi qalam uchiga tekkizishi kerak), shuningdek to‘rt nuqtali rang testi asbobida. Binokulyar ko‘rish haydovchi, uchuvchi, jarroh kabi kasblar uchun juda muhim.</p><h3>Ko‘rish funksiyalarini tekshirishda hamshiraning vazifalari</h3><ul><li>tekshiruv xonasi va asboblarni (jadvallar, Rot apparati, ko‘rsatgich, to‘siq, Rabkin jadvallari) tayyorlash;</li><li>bemorga tekshiruvning maqsadi va tartibini tushuntirish, uni qulay joylashtirish;</li><li>har bir ko‘zni alohida tekshirish, ko‘zni bosmasdan yopishni nazorat qilish;</li><li>natijalarni tibbiy hujjatga aniq va to‘g‘ri yozish;</li><li>to‘siq va ko‘rsatgichni har bir bemordan keyin dezinfeksiya qilish;</li><li>aholiga ko‘rish gigiyenasi (to‘g‘ri yoritish, kompyuterda ishlash tartibi, 20–20–20 qoidasi) bo‘yicha maslahat berish.</li></ul><p>Xulosa: ko‘ruv organi murakkab tuzilgan, nozik va o‘ta muhim a’zo. Uning tuzilishi va funksiyalarini chuqur bilish hamshiraga ko‘z kasalliklarini erta aniqlash, tekshiruvlarni to‘g‘ri o‘tkazish, bemorlarni sifatli parvarish qilish va aholi o‘rtasida profilaktik ishlarni samarali tashkil etish imkonini beradi.</p></section>", "lecture_toc": ["1. “Oftalmologiya” fani haqida tushuncha va uning tibbiyot fanlari orasidagi o‘rni", "2. Oftalmologiya fanining rivojlanish tarixi", "3. Ko‘ruv organi anatomiyasi", "4. Ko‘ruv organining faoliyati (ko‘rish funksiyalari)"], "tests": [{"q": "“Oftalmologiya” so‘zi qaysi tildan olingan?", "o": ["Yunon tilidan", "Lotin tilidan", "Arab tilidan", "Fors tilidan"], "a": 0}, {"q": "Inson tashqi muhit haqidagi ma’lumotning taxminan qancha qismini ko‘rish orqali oladi?", "o": ["80–90 foizini", "30–40 foizini", "50 foizini", "10–20 foizini"], "a": 0}, {"q": "Abu Ali ibn Sino ko‘z kasalliklarini “Tib qonunlari”ning qaysi kitobida bayon qilgan?", "o": ["3-kitobida", "1-kitobida", "5-kitobida", "2-kitobida"], "a": 0}, {"q": "Oftalmoskopni kim ixtiro qilgan?", "o": ["G. Gelmgols", "G. Snellen", "J. Daviel", "I. Kepler"], "a": 0}, {"q": "Katarakta ekstraksiyasini birinchi bo‘lib bajargan olim:", "o": ["J. Daviel", "A. Gullstrand", "F. Donders", "V. P. Filatov"], "a": 0}, {"q": "Tasvir to‘r pardada hosil bo‘lishini kim isbotlagan?", "o": ["I. Kepler", "Galen", "Gippokrat", "G. Snellen"], "a": 0}, {"q": "Ko‘ruv analizatori qaysi qismlardan iborat?", "o": ["Periferik qism, o‘tkazuvchi yo‘llar, po‘stloq markazi", "Ko‘z olmasi, qovoqlar, kon’yunktiva", "Shox parda, gavhar, to‘r parda", "Ko‘z kosasi, muskullar, ko‘z yoshi bezi"], "a": 0}, {"q": "Ko‘rish markazi bosh miyaning qaysi bo‘lagida joylashgan?", "o": ["Ensa bo‘lagida", "Peshona bo‘lagida", "Chakka bo‘lagida", "Tepa bo‘lagida"], "a": 0}, {"q": "Ko‘z olmasi devori qaysi pardalardan iborat?", "o": ["Fibroz, tomirli, to‘r parda", "Fibroz, shilliq, to‘r parda", "Shox, oqsil, shilliq parda", "Tomirli, shilliq, muskul qavat"], "a": 0}, {"q": "Fibroz parda qaysi qismlardan tashkil topgan?", "o": ["Shox parda va sklera", "Shox parda va rangdor parda", "Sklera va kon’yunktiva", "Rangdor parda va kiprikli tana"], "a": 0}, {"q": "Katta yoshli odamda shox pardaning gorizontal diametri:", "o": ["11–12 mm", "8 mm", "15 mm", "20 mm"], "a": 0}, {"q": "Shox parda qanday oziqlanadi?", "o": ["Ko‘z ichi suyuqligi, ko‘z yoshi va limb tomirlari hisobiga", "Faqat o‘z qon tomirlari orqali", "Shishasimon tana orqali", "Ko‘ruv nervi orqali"], "a": 0}, {"q": "Qon tomirlari yo‘q, lekin nerv tolalariga juda boy parda:", "o": ["Shox parda", "Sklera", "Xususiy tomirli parda", "Kiprikli tana"], "a": 0}, {"q": "Skleraning asosiy vazifasi:", "o": ["Ko‘zga shakl berish va himoya qilish", "Nurni sindirish", "Akkomodatsiya", "Ko‘z ichi suyuqligini ishlab chiqarish"], "a": 0}, {"q": "Tomirli parda qanday qismlardan iborat?", "o": ["Rangdor parda, kiprikli tana, xususiy tomirli parda", "Shox parda, sklera, limb", "Gavhar, shishasimon tana", "Sariq dog‘, ko‘ruv nervi diski"], "a": 0}, {"q": "Qorachiq ko‘zning qaysi qismida joylashgan?", "o": ["Rangdor pardada", "Shox pardada", "Gavharda", "To‘r pardada"], "a": 0}, {"q": "Qorachiqni toraytiruvchi muskulni qaysi nerv tolalari innervatsiya qiladi?", "o": ["Ko‘zni harakatlantiruvchi nervning parasimpatik tolalari", "Simpatik nerv tolalari", "Yuz nervi", "Uch shoxli nerv"], "a": 0}, {"q": "Ko‘z ichi suyuqligi qayerda ishlab chiqariladi?", "o": ["Kiprikli tanada", "Ko‘z yoshi bezida", "Gavharda", "Shishasimon tanada"], "a": 0}, {"q": "Akkomodatsiyani ta’minlaydigan tuzilma:", "o": ["Kiprikli tana muskuli va gavhar", "Sklera", "Ko‘ruv nervi", "Kon’yunktiva"], "a": 0}, {"q": "Kunduzgi va rangli ko‘rishni ta’minlovchi hujayralar:", "o": ["Kolbachalar", "Tayoqchalar", "Ganglioz hujayralar", "Pigment epiteliy"], "a": 0}, {"q": "Tayoqchalardagi ko‘ruv purpuri (rodopsin) hosil bo‘lishi uchun qaysi vitamin zarur?", "o": ["A vitamini", "C vitamini", "D vitamini", "B12 vitamini"], "a": 0}, {"q": "To‘r pardaning eng aniq ko‘rish nuqtasi:", "o": ["Sariq dog‘ning markaziy chuqurchasi", "Ko‘ruv nervi diski", "To‘r pardaning periferiyasi", "Tishsimon chiziq"], "a": 0}, {"q": "“Ko‘r dog‘” (Mariott dog‘i) qayerda joylashgan?", "o": ["Ko‘ruv nervi diskida", "Sariq dog‘da", "Shox pardada", "Gavharda"], "a": 0}, {"q": "Ko‘zning ichki tiniq muhitlari:", "o": ["Ko‘z ichi suyuqligi, gavhar, shishasimon tana", "Shox parda, sklera, gavhar", "Rangdor parda, gavhar, qorachiq", "Kon’yunktiva, ko‘z yoshi, gavhar"], "a": 0}, {"q": "Maklakov tonometri bo‘yicha ko‘z ichi bosimining normasi:", "o": ["18–26 mm sim. ust.", "5–10 mm sim. ust.", "30–40 mm sim. ust.", "120/80 mm sim. ust."], "a": 0}, {"q": "Gavharning sindirish kuchi taxminan:", "o": ["18–20 dioptriya", "40–43 dioptriya", "5 dioptriya", "60 dioptriya"], "a": 0}, {"q": "Ko‘z yoshi bezi qayerda joylashgan?", "o": ["Ko‘z kosasining yuqori-tashqi burchagida", "Ko‘zning ichki burchagida", "Pastki qovoqda", "Burun bo‘shlig‘ida"], "a": 0}, {"q": "Ko‘z olmasini harakatlantiruvchi muskullar soni:", "o": ["6 ta", "4 ta", "8 ta", "5 ta"], "a": 0}, {"q": "Tashqi to‘g‘ri muskulni qaysi nerv innervatsiya qiladi?", "o": ["Uzoqlashtiruvchi nerv (VI juft)", "G‘altak nervi (IV juft)", "Ko‘zni harakatlantiruvchi nerv (III juft)", "Yuz nervi (VII juft)"], "a": 0}, {"q": "Ko‘rish o‘tkirligi Sivtsev–Golovin jadvali bilan qanday masofadan tekshiriladi?", "o": ["5 m", "1 m", "3 m", "10 m"], "a": 0}, {"q": "Bemor jadvalning birinchi qatorini 1 m dan o‘qidi. Ko‘rish o‘tkirligi:", "o": ["0,02", "0,1", "0,2", "0,01"], "a": 0}, {"q": "Oq rang uchun ko‘ruv maydonining tashqi chegarasi normada:", "o": ["90°", "50°", "30°", "120°"], "a": 0}, {"q": "Rang ko‘rish qaysi jadvallar yordamida tekshiriladi?", "o": ["Rabkin polixromatik jadvallari", "Sivtsev–Golovin jadvali", "Orlova jadvali", "Snellen jadvali"], "a": 0}, {"q": "Qizil rangni sezmaslik qanday ataladi?", "o": ["Protanopiya", "Deyteranopiya", "Tritanopiya", "Gemianopsiya"], "a": 0}, {"q": "Gemeralopiya (“tovuq ko‘rlik”) – bu:", "o": ["Qorong‘ilik adaptatsiyasining buzilishi", "Rang ko‘rishning buzilishi", "Ko‘ruv maydonining yarmi tushib qolishi", "Ikkilanib ko‘rish"], "a": 0}, {"q": "Binokulyar ko‘rishni tekshirish usuli:", "o": ["Sokolov sinamasi (“kaftdagi teshik”)", "Tonometriya", "Perimetriya", "Rabkin jadvallari"], "a": 0}], "gallery": [{"f": "plakat.jpg", "t": "Mavzu bo‘yicha infografika-plakat", "d": "Mavzuning asosiy savollarini yorituvchi ko‘rgazmali plakat (muallif ishlanmasi)."}, {"f": "01_koz_kesimi_belgili.png", "t": "Ko‘z olmasining kesimi (belgilangan)", "d": "Pardalar, ichki muhitlar, ko‘ruv nervi va muskullar."}, {"f": "02_koz_kesimi_raqamli.png", "t": "Ko‘z olmasining kesimi (topshiriq uchun)", "d": "1–16 raqamli tuzilmalarni nomlang."}, {"f": "03_koruv_yoli.png", "t": "Ko‘ruv analizatori", "d": "Periferik qism, o‘tkazuvchi yo‘llar va po‘stloq markazi."}, {"f": "08_klaster_koruv_organi.png", "t": "Klaster: ko‘ruv organi", "d": "Ko‘z olmasi va yordamchi apparat tuzilmalari."}, {"f": "07_tarix_vaqt_chizigi.png", "t": "Oftalmologiya tarixi", "d": "Qadimgi davrdan XX asrgacha asosiy kashfiyotlar."}, {"f": "04_sivtsev_jadvali.png", "t": "Sivtsev–Golovin jadvali", "d": "Ko‘rish o‘tkirligini aniqlash jadvali namunasi."}, {"f": "05_koruv_maydoni.png", "t": "Ko‘ruv maydoni chegaralari", "d": "O‘ng ko‘z uchun oq rangda normal chegaralar."}, {"f": "06_rang_plastinka.png", "t": "Polixromatik plastinka", "d": "Rang ko‘rishni tekshirish namunasi (norma: 74)."}, {"f": "umumiy_plakat.jpg", "t": "Oftalmologiya: umumiy plakat", "d": "Fan haqida umumiy ko‘rgazmali plakat (muallif ishlanmasi)."}], "glossary": [{"t": "Adaptatsiya", "l": "adaptatio", "d": "Ko‘zning turli yoritilganlik darajasiga moslashishi (qorong‘ilik va yorug‘lik adaptatsiyasi)."}, {"t": "Akkomodatsiya", "l": "accommodatio", "d": "Ko‘zning gavhar egriligini o‘zgartirib, turli masofadagi narsalarni aniq ko‘rishga moslashishi."}, {"t": "Analizator", "l": "analysator", "d": "Ta’sirlarni qabul qiluvchi, o‘tkazuvchi va tahlil qiluvchi qismlardan iborat nerv tizimi; ko‘ruv analizatori."}, {"t": "Binokulyar ko‘rish", "l": "visus binocularis", "d": "Ikki ko‘z bilan birgalikda ko‘rib, narsani yagona, hajmli tasvir sifatida idrok etish."}, {"t": "Daltonizm", "l": "daltonismus", "d": "Qizil va yashil ranglarni farqlay olmaslik; rang ko‘rishning tug‘ma buzilishi."}, {"t": "Deyteranopiya", "l": "deuteranopia", "d": "Yashil rangni sezmaslik."}, {"t": "Dioptriya", "l": "dioptria", "d": "Linza yoki optik tizimning sindirish kuchi birligi (D); fokus masofasi 1 m bo‘lgan linza kuchi."}, {"t": "Fotoretseptorlar", "l": "photoreceptores", "d": "To‘r pardaning yorug‘lik sezuvchi hujayralari – tayoqchalar va kolbachalar."}, {"t": "Fuziya", "l": "fusio", "d": "Ikki ko‘zdagi tasvirlarning bosh miya po‘stlog‘ida yagona tasvirga qo‘shilishi."}, {"t": "Gavhar", "l": "lens", "d": "Rangdor parda va shishasimon tana orasidagi ikki tomoni qavariq, tiniq, elastik linza."}, {"t": "Gemeralopiya", "l": "hemeralopia", "d": "Qorong‘ilik adaptatsiyasining buzilishi, g‘ira-shira va qorong‘ida yomon ko‘rish (“tovuq ko‘rlik”)."}, {"t": "Gemianopsiya", "l": "hemianopsia", "d": "Ko‘ruv maydonining yarmi tushib qolishi."}, {"t": "Iris", "l": "iris", "d": "Rangdor parda – tomirli pardaning oldingi qismi, markazida qorachiq joylashgan."}, {"t": "Kiprikli tana", "l": "corpus ciliare", "d": "Tomirli pardaning o‘rta qismi; ko‘z ichi suyuqligini ishlab chiqaradi, akkomodatsiyada qatnashadi."}, {"t": "Kolbachalar", "l": "coni", "d": "Kunduzgi va rangli ko‘rishni ta’minlovchi fotoretseptorlar; sariq dog‘da ko‘p."}, {"t": "Kon’yunktiva", "l": "conjunctiva", "d": "Qovoqlarning ichki yuzasini va ko‘z olmasining old qismini qoplovchi shilliq parda."}, {"t": "Ko‘ruv maydoni", "l": "campus visus", "d": "Ko‘z bir nuqtaga qimirlamay qaraganda bir vaqtda ko‘ra oladigan fazo."}, {"t": "Ko‘ruv nervi diski", "l": "discus nervi optici", "d": "Ko‘ruv nervi tolalarining ko‘z olmasidan chiqish joyi; “ko‘r dog‘”."}, {"t": "Ko‘z ichi bosimi", "l": "tensio intraocularis", "d": "Ko‘z ichidagi suyuqlik bosimi; Maklakov bo‘yicha normasi 18–26 mm sim. ust."}, {"t": "Limb", "l": "limbus corneae", "d": "Shox pardaning skleraga o‘tish joyi, kengligi taxminan 1 mm."}, {"t": "Makula", "l": "macula lutea", "d": "Sariq dog‘ – to‘r pardaning eng aniq ko‘rish sohasi."}, {"t": "Oftalmologiya", "l": "ophthalmologia", "d": "Ko‘ruv a’zosining tuzilishi, faoliyati va kasalliklarini o‘rganuvchi tibbiyot fani."}, {"t": "Oftalmoskopiya", "l": "ophthalmoscopia", "d": "Ko‘z tubini maxsus asbob – oftalmoskop yordamida tekshirish."}, {"t": "Orbita", "l": "orbita", "d": "Ko‘z kosasi – yetti suyakdan hosil bo‘lgan, ko‘z olmasi joylashgan bo‘shliq."}, {"t": "Perimetriya", "l": "perimetria", "d": "Ko‘ruv maydonini perimetr asbobi yordamida tekshirish."}, {"t": "Presbiopiya", "l": "presbyopia", "d": "Yoshga bog‘liq akkomodatsiyaning susayishi, yaqindan ko‘rishning qiyinlashishi."}, {"t": "Protanopiya", "l": "protanopia", "d": "Qizil rangni sezmaslik."}, {"t": "Qorachiq", "l": "pupilla", "d": "Rangdor parda markazidagi yumaloq teshik, ko‘zga tushadigan yorug‘lik miqdorini boshqaradi."}, {"t": "Refraksiya", "l": "refractio", "d": "Ko‘zning optik tizimida nurlarning sinishi."}, {"t": "Retina", "l": "retina", "d": "To‘r parda – yorug‘likni qabul qilib, nerv impulsiga aylantiruvchi ichki parda."}, {"t": "Rodopsin", "l": "rhodopsinum", "d": "Tayoqchalardagi ko‘ruv purpuri; hosil bo‘lishi uchun A vitamini zarur."}, {"t": "Sklera", "l": "sclera", "d": "Oqsil parda – fibroz pardaning oq, noshaffof qismi."}, {"t": "Skotoma", "l": "scotoma", "d": "Ko‘ruv maydoni ichidagi ko‘rmaydigan soha."}, {"t": "Tayoqchalar", "l": "bacilli", "d": "G‘ira-shira va qorong‘ida ko‘rishni ta’minlovchi fotoretseptorlar."}, {"t": "Tonometriya", "l": "tonometria", "d": "Ko‘z ichi bosimini o‘lchash."}, {"t": "Tritanopiya", "l": "tritanopia", "d": "Ko‘k rangni sezmaslik."}, {"t": "Trixromaziya", "l": "trichromasia", "d": "Uch asosiy rangni (qizil, yashil, ko‘k) normal sezish."}, {"t": "Visus", "l": "visus", "d": "Ko‘rish o‘tkirligi – ko‘zning ikki nuqtani alohida ko‘ra olish qobiliyati; normasi 1,0."}, {"t": "Xiazma", "l": "chiasma opticum", "d": "Ko‘ruv nervlarining qisman kesishgan joyi."}, {"t": "Xorioideya", "l": "chorioidea", "d": "Xususiy tomirli parda – to‘r pardaning tashqi qavatlarini oziqlantiradi."}, {"t": "Shishasimon tana", "l": "corpus vitreum", "d": "Gavhar orqasidagi tiniq iviqsimon modda, ko‘z hajmining 2/3 qismini egallaydi."}, {"t": "Shox parda", "l": "cornea", "d": "Fibroz pardaning oldingi tiniq qismi; nurni o‘tkazadi va sindiradi."}], "slides": [{"title": "Oftalmologiyaning rivojlanish tarixi. Ko‘ruv organi anatomiyasi. Ko‘zning ko‘rish faoliyati", "note": "Assalomu alaykum, aziz o‘quvchilar! Bugun “Oftalmologiyada hamshiralik ishi” modulining birinchi mavzusi – oftalmologiyaning rivojlanish tarixi, ko‘ruv organi anatomiyasi va ko‘zning ko‘rish faoliyati bilan tanishamiz."}, {"title": "Mashg‘ulot rejasi va o‘qitish natijalari", "note": "Mashg‘ulot to‘rt savoldan iborat: oftalmologiya fani va uning tibbiyotdagi o‘rni, fanning rivojlanish tarixi, ko‘ruv organining anatomiyasi va ko‘zning ko‘rish funksiyalari. Dars yakunida siz ko‘zning tuzilishini va beshta asosiy ko‘rish funksiyasini aytib bera olasiz."}, {"title": "Oftalmologiya nima?", "note": "Oftalmologiya so‘zi yunoncha “oftalmos” – ko‘z va “logos” – ta’limot so‘zlaridan olingan. Bu fan ko‘ruv a’zosining tuzilishi, faoliyati va kasalliklarini o‘rganadi. Inson tashqi muhit haqidagi ma’lumotlarning sakson–to‘qson foizini ko‘zi orqali oladi. Jahon sog‘liqni saqlash tashkilotiga ko‘ra, dunyoda ikki milliard ikki yuz million kishida ko‘rish buzilishi mavjud, ularning deyarli yarmida bu holatning oldini olish mumkin edi."}, {"title": "Oftalmologiyaning boshqa fanlar bilan bog‘liqligi", "note": "Ko‘plab umumiy kasalliklar ko‘zda o‘z aksini topadi. Gipertoniyada ko‘z tubi tomirlari torayadi, qandli diabetda diabetik retinopatiya va katarakta rivojlanadi. Shuning uchun oftalmolog terapevt, nevropatolog va endokrinolog bilan hamkorlikda ishlaydi."}, {"title": "Oftalmologiyada hamshiraning vazifalari", "note": "Hamshira bemorni qabul qiladi va tekshiruvga tayyorlaydi, ko‘rish o‘tkirligini aniqlashda ishtirok etadi, tomchi dori tomizadi, malham qo‘yadi va ko‘zni yuvadi. Shikastlarda birinchi yordam ko‘rsatadi. Ko‘z infeksiyalari oson yuqgani uchun aseptika qoidalariga qat’iy rioya qilish shart."}, {"title": "Oftalmologiya tarixi: asosiy bosqichlar", "note": "Ko‘z kasalliklari haqidagi dastlabki ma’lumotlar qadimgi Misrning Ebers papirusida uchraydi. Hindistonlik tabib Sushruta katarakta operatsiyasini bajargan. To‘qqizinchi asrda Hunayn ibn Ishoq “Ko‘z haqida o‘n maqola” darsligini yozgan. Yangi davrda Kepler tasvir to‘r pardada hosil bo‘lishini isbotlagan, Daviel kataraktani chiqarib olgan, Gelmgols oftalmoskopni, Snellen esa ko‘rish jadvalini yaratgan."}, {"title": "Abu Ali ibn Sino va Sharq tabobati", "note": "Buyuk vatandoshimiz Abu Ali ibn Sino “Tib qonunlari” asarining uchinchi kitobida ko‘z anatomiyasi va kasalliklarini batafsil bayon qilgan. U ko‘zning olti tashqi muskulini, ko‘ruv nervi kesishmasini tasvirlagan, traxoma, katarakta va tungi ko‘rlik haqida yozgan. Uning asarlari bir necha asr davomida Yevropa universitetlarida darslik bo‘lgan."}, {"title": "XX asr va hozirgi zamon", "note": "Yigirmanchi asrda Filatov shox pardani ko‘chirib o‘tkazish usulini, Fyodorov esa ko‘z mikroxirurgiyasi va sun’iy gavhar qo‘yishni rivojlantirdi. O‘zbekistonda traxoma ommaviy kasallik sifatida tugatildi, bugun esa kataraktani fakoemulsifikatsiya usulida olib tashlash va lazer operatsiyalari muvaffaqiyatli bajarilmoqda."}, {"title": "Ko‘ruv analizatori", "note": "Ko‘ruv analizatori uch qismdan iborat. Periferik qism – ko‘z olmasi va to‘r parda. O‘tkazuvchi yo‘llar – ko‘ruv nervi, ko‘ruv nervlari kesishmasi – xiazma, ko‘ruv yo‘llari va tashqi tizzasimon tanalar. Markaziy qism – bosh miyaning ensa bo‘lagidagi ko‘rish markazi."}, {"title": "Ko‘z olmasining tuzilishi", "note": "Ko‘z olmasi sharsimon, uning old-orqa o‘qi o‘rtacha yigirma to‘rt millimetr. Devori uch pardadan iborat: tashqi fibroz parda – shox parda va sklera; o‘rta tomirli parda – rangdor parda, kiprikli tana va xususiy tomirli parda; ichki – to‘r parda. Ichida esa ko‘z ichi suyuqligi, gavhar va shishasimon tana joylashgan."}, {"title": "Tashqi – fibroz parda", "note": "Shox parda fibroz pardaning oltidan bir qismini egallaydi. U tiniq, qon tomirlari yo‘q, lekin nerv tolalariga juda boy, shuning uchun unga tushgan kichik yot jism ham kuchli og‘riq beradi. Sindirish kuchi qirq–qirq uch dioptriya. Sklera esa oq, zich parda bo‘lib, ko‘zga shakl beradi va uni himoya qiladi."}, {"title": "O‘rta – tomirli parda", "note": "Tomirli parda uch qismdan iborat. Rangdor parda ko‘zga rang beradi, uning markazidagi qorachiq fotoapparat diafragmasi kabi ko‘zga tushadigan yorug‘likni boshqaradi. Kiprikli tana ko‘z ichi suyuqligini ishlab chiqaradi va akkomodatsiyani ta’minlaydi. Xususiy tomirli parda to‘r pardani oziqlantiradi."}, {"title": "Ichki – to‘r parda", "note": "To‘r parda yorug‘likni nerv impulsiga aylantiradi. Unda ikki xil fotoretseptor bor: tayoqchalar qorong‘ida ko‘rishni, kolbachalar esa kunduzgi va rangli ko‘rishni ta’minlaydi. Eng aniq ko‘rish nuqtasi – sariq dog‘. Ko‘ruv nervi diskida fotoretseptorlar yo‘q, shuning uchun u ko‘r dog‘ deb ataladi."}, {"title": "Ichki tiniq muhitlar va yordamchi apparat", "note": "Ko‘zning ichki tiniq muhitlari – ko‘z ichi suyuqligi, gavhar va shishasimon tana. Ko‘z ichi bosimining normasi Maklakov bo‘yicha o‘n sakkiz–yigirma olti millimetr simob ustuni. Yordamchi apparatga ko‘z kosasi, qovoqlar, kon’yunktiva, ko‘z yoshi a’zolari va oltita harakatlantiruvchi muskul kiradi."}, {"title": "Ko‘zning 5 ta ko‘rish funksiyasi", "note": "Ko‘zning beshta asosiy ko‘rish funksiyasi bor: markaziy ko‘rish, periferik ko‘rish, rang ko‘rish, yorug‘lik sezish va binokulyar ko‘rish. Endi ularni qanday tekshirishni ko‘rib chiqamiz."}, {"title": "Ko‘rish o‘tkirligini tekshirish", "note": "Ko‘rish o‘tkirligi Sivtsev–Golovin jadvali bilan besh metr masofadan tekshiriladi. Har bir ko‘z alohida tekshiriladi, ikkinchi ko‘z to‘siq bilan bosilmasdan yopiladi. Normal ko‘rish o‘tkirligi birga teng. Agar bemor birinchi qatorni ham ko‘rmasa, Snellen formulasi qo‘llaniladi: ko‘rish o‘tkirligi bemor o‘qigan masofani ellikka bo‘lganiga teng."}, {"title": "Ko‘ruv maydoni va rang ko‘rish", "note": "Ko‘ruv maydoni perimetr asbobida tekshiriladi. Oq rang uchun tashqi chegara to‘qson daraja, ichki chegara ellik besh daraja. Rang ko‘rish esa Rabkin polixromatik jadvallari bilan tekshiriladi. Qizil rangni sezmaslik protanopiya, yashilni sezmaslik deyteranopiya deb ataladi."}, {"title": "Yorug‘lik sezish va binokulyar ko‘rish", "note": "Ko‘z qorong‘ilikka qirq–oltmish daqiqada moslashadi. Bu jarayon buzilsa, gemeralopiya – tovuq ko‘rlik yuzaga keladi; uning ko‘p uchraydigan sababi A vitamini yetishmovchiligidir. Binokulyar ko‘rish ikki ko‘zdagi tasvirlarning yagona tasvirga qo‘shilishi bo‘lib, Sokolov sinamasi bilan tekshiriladi."}, {"title": "Xulosa", "note": "Xulosa qilib aytganda, oftalmologiya ijtimoiy ahamiyati juda yuqori fan. Ko‘z olmasi uch parda va uch tiniq muhitdan iborat, ko‘zning beshta ko‘rish funksiyasi mavjud. Hamshira ko‘z kasalliklarini erta aniqlash va profilaktikada muhim o‘rin tutadi. E’tiboringiz uchun rahmat! Endi nazorat savollari va testlarga o‘ting."}], "video_len": "7:34"};
